using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Verifies the wire contract between our code and the payment provider's REST API:
/// what we send on the way out, and what we accept on the way back in, including the
/// provider's outright refusal (402).
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var sut = CreateSut(handler);

        await sut.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.LastRequest.RequestUri!.PathAndQuery);

        var sentBody = JsonDocument.Parse(handler.LastRequestBody!).RootElement;
        Assert.Equal("ORD-1", sentBody.GetProperty("reference").GetString());
        Assert.Equal(42.50m, sentBody.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", sentBody.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"declined"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_outright_refusal_by_the_provider_is_read_back_as_declined()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.PaymentRequired, string.Empty);
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_provider_error_surfaces_instead_of_being_silently_swallowed()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.InternalServerError, string.Empty);
        var sut = CreateSut(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_response_missing_the_expected_status_field_is_treated_as_declined()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"unexpected":"shape"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    private static Infrastructure.HttpPaymentGateway CreateSut(HttpMessageHandler handler)
    {
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") };
        return new Infrastructure.HttpPaymentGateway(client);
    }

    private sealed class StubHttpMessageHandler(HttpStatusCode statusCode, string responseBody) : HttpMessageHandler
    {
        public HttpRequestMessage? LastRequest { get; private set; }
        public string? LastRequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            LastRequestBody = request.Content is null
                ? null
                : await request.Content.ReadAsStringAsync(cancellationToken);

            return new HttpResponseMessage(statusCode)
            {
                Content = new StringContent(responseBody, Encoding.UTF8, "application/json"),
            };
        }
    }
}

